<script setup lang="ts">
import { onMounted, ref } from "vue";
import AppBreadcrumb from "@/components/AppBreadcrumb.vue";
import ConfirmDialog from "@/components/ConfirmDialog.vue";
import PageHeader from "@/components/PageHeader.vue";
import StatusBadge from "@/components/StatusBadge.vue";
import { ApiError } from "@/services/http";
import { createBeneficiary, createBeneficiaryCondition, getBeneficiaryOptions, listBeneficiaryConditions, listConditionOptions, listBeneficiaries, toggleBeneficiary, toggleBeneficiaryCondition, updateBeneficiary, updateBeneficiaryCondition, type Beneficiary, type BeneficiaryCondition, type BeneficiaryOptions, type BeneficiaryPayload, type ConditionOption } from "@/services/beneficiarios";

const items = ref<Beneficiary[]>([]); const options = ref<BeneficiaryOptions>({ tiposBeneficiario: [], carreras: [] }); const conditionOptions = ref<ConditionOption[]>([]); const search = ref(""); const page = ref(1); const pagination = ref({ page: 1, pageSize: 10, total: 0, totalPages: 0 }); const loading = ref(false); const saving = ref(false); const error = ref(""); const formError = ref(""); const success = ref(""); const editing = ref<Beneficiary | null>(null); const showForm = ref(false); const confirmTarget = ref<Beneficiary | null>(null); const activeTab = ref<"general" | "conditions">("general");
const conditions = ref<BeneficiaryCondition[]>([]); const conditionPage = ref(1); const conditionPagination = ref({ page: 1, pageSize: 10, total: 0, totalPages: 0 }); const conditionLoading = ref(false); const conditionError = ref(""); const conditionSearch = ref(""); const conditionState = ref<"all" | "active" | "inactive">("all"); const conditionEditing = ref<BeneficiaryCondition | null>(null); const showConditionForm = ref(false); const conditionSaving = ref(false);
const form = ref({ primerNombre: "", segundoNombre: "", primerApellido: "", segundoApellido: "", numeroIdentificacion: "", telefonoPrincipal: "", correoPersonal: "", fechaNacimiento: "", idTipoBeneficiario: 0, idCarrera: null as number | null, numeroCuenta: "", correoInstitucional: "", codigoCarne: "", estadoAcademico: "" });
const conditionForm = ref({ idTipoCondicion: 0, descripcionCondicion: "", esTemporal: false, fechaInicio: "", fechaFinEstimada: "", requiereRevision: false });
const message = (value: unknown) => value instanceof ApiError ? value.message : "Ocurrió un error inesperado";
async function load() { loading.value = true; error.value = ""; try { const result = await listBeneficiaries(search.value, page.value); items.value = result.items; pagination.value = result.pagination; } catch (cause) { error.value = message(cause); } finally { loading.value = false; } }
async function loadOptions() { try { options.value = await getBeneficiaryOptions(); conditionOptions.value = await listConditionOptions(); } catch (cause) { error.value = message(cause); } }
function edit(item: Beneficiary | null) { editing.value = item; activeTab.value = "general"; formError.value = ""; form.value = { primerNombre: item?.primerNombre ?? "", segundoNombre: item?.segundoNombre ?? "", primerApellido: item?.primerApellido ?? "", segundoApellido: item?.segundoApellido ?? "", numeroIdentificacion: item?.numeroIdentificacion ?? "", telefonoPrincipal: item?.telefonoPrincipal ?? "", correoPersonal: item?.correoPersonal ?? "", fechaNacimiento: item?.fechaNacimiento?.slice(0, 10) ?? "", idTipoBeneficiario: item?.idTipoBeneficiario ?? 0, idCarrera: item?.idCarrera ?? null, numeroCuenta: item?.numeroCuenta ?? "", correoInstitucional: item?.correoInstitucional ?? "", codigoCarne: item?.codigoCarne ?? "", estadoAcademico: item?.estadoAcademico ?? "" }; showForm.value = true; if (item) void loadConditions(); }
function payload(): BeneficiaryPayload { return { person: { primerNombre: form.value.primerNombre, segundoNombre: form.value.segundoNombre || null, primerApellido: form.value.primerApellido, segundoApellido: form.value.segundoApellido || null, numeroIdentificacion: form.value.numeroIdentificacion || null, telefonoPrincipal: form.value.telefonoPrincipal || null, correoPersonal: form.value.correoPersonal || null, fechaNacimiento: form.value.fechaNacimiento ? new Date(`${form.value.fechaNacimiento}T00:00:00`) : null }, beneficiary: { idTipoBeneficiario: form.value.idTipoBeneficiario, idCarrera: form.value.idCarrera, numeroCuenta: form.value.numeroCuenta || null, correoInstitucional: form.value.correoInstitucional || null, codigoCarne: form.value.codigoCarne || null, estadoAcademico: form.value.estadoAcademico || null } } as BeneficiaryPayload; }
async function save() { formError.value = ""; saving.value = true; try { const creating = !editing.value; if (creating) await createBeneficiary(payload()); else await updateBeneficiary(editing.value!.idBeneficiario, payload()); showForm.value = false; success.value = creating ? "Beneficiario creado correctamente." : "Beneficiario actualizado correctamente."; await load(); } catch (cause) { formError.value = message(cause); } finally { saving.value = false; } }
async function loadConditions() { if (!editing.value) return; conditionLoading.value = true; conditionError.value = ""; try { const result = await listBeneficiaryConditions(editing.value.idBeneficiario, { page: conditionPage.value, search: conditionSearch.value, estado: conditionState.value }); conditions.value = result.items; conditionPagination.value = result.pagination; } catch (cause) { conditionError.value = message(cause); } finally { conditionLoading.value = false; } }
function openCondition(item: BeneficiaryCondition | null) { conditionEditing.value = item; conditionForm.value = { idTipoCondicion: item?.idTipoCondicion ?? conditionOptions.value[0]?.idTipoValor ?? 0, descripcionCondicion: item?.descripcionCondicion ?? "", esTemporal: item?.esTemporal ?? false, fechaInicio: item?.fechaInicio?.slice(0, 10) ?? "", fechaFinEstimada: item?.fechaFinEstimada?.slice(0, 10) ?? "", requiereRevision: item?.requiereRevision ?? false }; showConditionForm.value = true; }
async function saveCondition() { if (!editing.value || !conditionForm.value.idTipoCondicion) return; conditionSaving.value = true; conditionError.value = ""; try { const data = { ...conditionForm.value, descripcionCondicion: conditionForm.value.descripcionCondicion || null, fechaInicio: conditionForm.value.fechaInicio ? new Date(`${conditionForm.value.fechaInicio}T00:00:00`) : null, fechaFinEstimada: conditionForm.value.fechaFinEstimada ? new Date(`${conditionForm.value.fechaFinEstimada}T00:00:00`) : null }; if (conditionEditing.value) await updateBeneficiaryCondition(editing.value.idBeneficiario, conditionEditing.value.idBeneficiarioCondicion, data); else await createBeneficiaryCondition(editing.value.idBeneficiario, data); showConditionForm.value = false; success.value = "Condición guardada correctamente."; await loadConditions(); } catch (cause) { conditionError.value = message(cause); } finally { conditionSaving.value = false; } }
async function toggleCondition(item: BeneficiaryCondition) { if (!editing.value || !window.confirm(`¿Confirma ${item.estadoBeneficiarioCondicion ? "desactivar" : "activar"} esta condición?`)) return; try { await toggleBeneficiaryCondition(editing.value.idBeneficiario, item.idBeneficiarioCondicion, !item.estadoBeneficiarioCondicion); await loadConditions(); } catch (cause) { conditionError.value = message(cause); } }
function askToggle(item: Beneficiary) { confirmTarget.value = item; } async function toggle() { const item = confirmTarget.value; if (!item) return; confirmTarget.value = null; try { await toggleBeneficiary(item.idBeneficiario, !item.estadoBeneficiario); success.value = `Beneficiario ${item.estadoBeneficiario ? "desactivado" : "activado"} correctamente.`; await load(); } catch (cause) { error.value = message(cause); } }
function changePage(nextPage: number) { page.value = nextPage; void load(); } function changeConditionPage(nextPage: number) { conditionPage.value = nextPage; void loadConditions(); }
onMounted(() => { void Promise.all([load(), loadOptions()]); });
</script>

<template>
  <AppBreadcrumb :items="[{ label: 'Administración', to: '/' }, { label: 'Operación' }, { label: 'Beneficiarios' }]" /><PageHeader eyebrow="Operación" title="Beneficiarios" description="Administración de personas habilitadas para utilizar los servicios de acceso." action-label="Nuevo beneficiario" @action="edit(null)" />
  <div v-if="success" class="bo-notice bo-notice-success">{{ success }}</div><div v-if="error" class="bo-state bo-state-error">{{ error }} <button class="bo-link" @click="load">Reintentar</button></div>
  <section class="bo-card"><form class="bo-toolbar" @submit.prevent="load"><input v-model="search" placeholder="Buscar por nombre, cuenta o carné..." aria-label="Buscar beneficiarios" /><button class="bo-btn bo-btn-primary">Filtrar</button></form><div v-if="loading" class="bo-state">Cargando beneficiarios...</div><div v-else-if="!items.length" class="bo-state"><strong>No hay beneficiarios registrados.</strong><span>Ajuste la búsqueda o cree un nuevo beneficiario.</span></div><div v-else class="bo-table-wrap"><table><thead><tr><th>Persona</th><th>Identificación</th><th>Cuenta</th><th>Tipo</th><th>Carrera</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in items" :key="item.idBeneficiario"><td><strong>{{ item.primerApellido }}, {{ item.primerNombre }}</strong></td><td>{{ item.numeroIdentificacion ?? "-" }}</td><td>{{ item.numeroCuenta ?? "-" }}</td><td>{{ item.nombreTipoBeneficiario }}</td><td>{{ item.nombreCarrera ?? "-" }}</td><td><StatusBadge :active="item.estadoBeneficiario" /></td><td><div class="bo-actions"><button class="bo-action" @click="edit(item)">Editar</button><button class="bo-action" :class="{ danger: item.estadoBeneficiario }" @click="askToggle(item)">{{ item.estadoBeneficiario ? "Desactivar" : "Activar" }}</button></div></td></tr></tbody></table></div><footer v-if="!loading" class="bo-pagination"><span>{{ pagination.total }} registros · Página {{ pagination.page }} de {{ Math.max(pagination.totalPages, 1) }}</span><div><button class="bo-page-button" :disabled="page <= 1" @click="changePage(page - 1)">Anterior</button><button class="bo-page-button" :disabled="page >= pagination.totalPages" @click="changePage(page + 1)">Siguiente</button></div></footer></section>
  <div v-if="showForm" class="bo-modal-backdrop" @click.self="showForm = false"><section class="bo-modal beneficiary-modal"><header><div><span class="bo-eyebrow">{{ editing ? "Editar registro" : "Nuevo registro" }}</span><h2>{{ editing ? "Editar beneficiario" : "Crear beneficiario" }}</h2></div><button class="bo-close" type="button" @click="showForm = false">×</button></header><nav class="beneficiary-tabs"><button :class="{ active: activeTab === 'general' }" @click="activeTab = 'general'">Información general</button><button v-if="editing" :class="{ active: activeTab === 'conditions' }" @click="activeTab = 'conditions'; loadConditions()">Condiciones</button></nav><form v-if="activeTab === 'general'" class="bo-form" @submit.prevent="save"><div class="bo-form-grid"><label>Primer nombre *<input v-model="form.primerNombre" maxlength="80" required /></label><label>Segundo nombre<input v-model="form.segundoNombre" maxlength="80" /></label><label>Primer apellido *<input v-model="form.primerApellido" maxlength="80" required /></label><label>Segundo apellido<input v-model="form.segundoApellido" maxlength="80" /></label><label>Identificación<input v-model="form.numeroIdentificacion" maxlength="30" /></label><label>Fecha de nacimiento<input v-model="form.fechaNacimiento" type="date" /></label><label>Teléfono<input v-model="form.telefonoPrincipal" maxlength="30" /></label><label>Correo personal<input v-model="form.correoPersonal" maxlength="150" type="email" /></label><label>Tipo de beneficiario *<select v-model.number="form.idTipoBeneficiario" required><option :value="0" disabled>Seleccione...</option><option v-for="item in options.tiposBeneficiario" :key="item.idTipoValor" :value="item.idTipoValor">{{ item.codigoTipoValor }} · {{ item.nombreTipoValor }}</option></select></label><label>Carrera<select v-model="form.idCarrera"><option :value="null">Sin carrera</option><option v-for="item in options.carreras" :key="item.idCarrera" :value="item.idCarrera">{{ item.codigoCarrera }} · {{ item.nombreCarrera }}</option></select></label><label>Número de cuenta<input v-model="form.numeroCuenta" maxlength="20" /></label><label>Correo institucional<input v-model="form.correoInstitucional" maxlength="150" type="email" /></label><label>Código de carné<input v-model="form.codigoCarne" maxlength="50" /></label><label>Estado académico<input v-model="form.estadoAcademico" maxlength="30" /></label></div><p v-if="formError" class="bo-form-error">{{ formError }}</p><footer class="form-actions"><button type="button" class="bo-btn" @click="showForm = false">Cancelar</button><button class="bo-btn bo-btn-primary" :disabled="saving">{{ saving ? "Guardando..." : "Guardar" }}</button></footer></form><section v-else class="conditions-panel"><div class="conditions-toolbar"><button class="bo-btn bo-btn-primary" :disabled="!conditionOptions.length" @click="openCondition(null)">Nueva condición</button><input v-model="conditionSearch" placeholder="Buscar condición..." @keyup.enter="conditionPage = 1; loadConditions()" /><select v-model="conditionState" @change="conditionPage = 1; loadConditions()"><option value="all">Todos</option><option value="active">Activas</option><option value="inactive">Inactivas</option></select></div><p v-if="!conditionOptions.length" class="bo-form-note">No hay valores activos registrados para el catálogo TIPO_CONDICION.</p><div v-if="conditionLoading" class="bo-state">Cargando condiciones...</div><div v-else-if="conditionError" class="bo-state bo-state-error">{{ conditionError }} <button class="bo-link" @click="loadConditions">Reintentar</button></div><div v-else-if="!conditions.length" class="bo-state">No hay condiciones registradas para este beneficiario.</div><div v-else class="bo-table-wrap"><table><thead><tr><th>Tipo</th><th>Descripción</th><th>Temporal</th><th>Inicio</th><th>Fin estimada</th><th>Revisión</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in conditions" :key="String(item.idBeneficiarioCondicion)"><td>{{ item.nombreTipoCondicion }}</td><td>{{ item.descripcionCondicion ?? "-" }}</td><td>{{ item.esTemporal ? "Sí" : "No" }}</td><td>{{ item.fechaInicio?.slice(0, 10) ?? "-" }}</td><td>{{ item.fechaFinEstimada?.slice(0, 10) ?? "-" }}</td><td>{{ item.requiereRevision ? "Sí" : "No" }}</td><td><StatusBadge :active="item.estadoBeneficiarioCondicion" /></td><td><div class="bo-actions"><button class="bo-action" @click="openCondition(item)">Editar</button><button class="bo-action" :class="{ danger: item.estadoBeneficiarioCondicion }" @click="toggleCondition(item)">{{ item.estadoBeneficiarioCondicion ? "Desactivar" : "Activar" }}</button></div></td></tr></tbody></table></div><footer v-if="!conditionLoading" class="bo-pagination"><span>{{ conditionPagination.total }} condiciones · Página {{ conditionPagination.page }} de {{ Math.max(conditionPagination.totalPages, 1) }}</span><div><button class="bo-page-button" :disabled="conditionPage <= 1" @click="changeConditionPage(conditionPage - 1)">Anterior</button><button class="bo-page-button" :disabled="conditionPage >= conditionPagination.totalPages" @click="changeConditionPage(conditionPage + 1)">Siguiente</button></div></footer></section></section></div>
  <div v-if="showConditionForm" class="bo-modal-backdrop" @click.self="showConditionForm = false"><section class="bo-modal condition-modal"><header><div><span class="bo-eyebrow">Beneficiario</span><h2>{{ conditionEditing ? "Editar condición" : "Nueva condición" }}</h2></div><button class="bo-close" @click="showConditionForm = false">×</button></header><form class="bo-form" @submit.prevent="saveCondition"><label>Tipo de condición *<select v-model.number="conditionForm.idTipoCondicion" required><option :value="0" disabled>Seleccione...</option><option v-for="item in conditionOptions" :key="item.idTipoValor" :value="item.idTipoValor">{{ item.nombreTipoValor }}</option></select></label><label>Descripción<textarea v-model="conditionForm.descripcionCondicion" maxlength="1000" rows="3" /></label><label class="bo-check-label"><input v-model="conditionForm.esTemporal" type="checkbox" /> Es temporal</label><label>Fecha de inicio<input v-model="conditionForm.fechaInicio" type="date" /></label><label>Fecha de fin estimada<input v-model="conditionForm.fechaFinEstimada" type="date" /></label><label class="bo-check-label"><input v-model="conditionForm.requiereRevision" type="checkbox" /> Requiere revisión</label><footer class="form-actions"><button type="button" class="bo-btn" @click="showConditionForm = false">Cancelar</button><button class="bo-btn bo-btn-primary" :disabled="conditionSaving || !conditionForm.idTipoCondicion">Guardar</button></footer></form></section></div>
  <ConfirmDialog :open="Boolean(confirmTarget)" title="Cambiar estado del beneficiario" :message="confirmTarget ? `¿Desea ${confirmTarget.estadoBeneficiario ? 'desactivar' : 'activar'} este beneficiario?` : ''" :confirm-label="confirmTarget?.estadoBeneficiario ? 'Desactivar' : 'Activar'" @confirm="toggle" @cancel="confirmTarget = null" />
</template>

<style scoped>.beneficiary-tabs { display: flex; gap: 4px; margin-bottom: 16px; border-bottom: 1px solid var(--bo-line); }.beneficiary-tabs button { padding: 10px 14px; border: 0; border-bottom: 2px solid transparent; color: var(--bo-muted); background: transparent; cursor: pointer; font-size: 12px; font-weight: 700; }.beneficiary-tabs button.active { color: var(--bo-blue); border-bottom-color: var(--bo-blue); }.beneficiary-modal { width: min(900px, calc(100vw - 32px)); }.condition-modal { width: min(560px, calc(100vw - 32px)); }.conditions-toolbar { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 12px; }.conditions-toolbar input,.conditions-toolbar select { min-width: 150px; flex: 1; padding: 9px; border: 1px solid var(--bo-line); border-radius: 6px; }.conditions-toolbar button { flex: 0 0 auto; }</style>
